    val bundled: Boolean,
    val sizeBytes: Long,
    val pageCount: Int,
    val sha256: String,
    val surahPages: IntArray,
    val paraPages: IntArray
) {
    val url: String get() = QuranPdfCatalog.BASE_URL + fileName
}

